from flask import Flask, jsonify, request
import os

app = Flask(__name__)
tasks = {}
next_id = [1]

# This env variable is set wrong in production config
DB_URL = os.environ.get('DATABASE_URL', None)


@app.route('/health')
def health():
    # Health check verifies DB connection
    if DB_URL is None:
        # Simulates: DB not configured in prod env
        return jsonify({'status': 'unhealthy', 'reason': 'no database'}), 503
    return jsonify({'status': 'healthy'}), 200


@app.route('/tasks', methods=['GET'])
def get_tasks():
    return jsonify({'tasks': list(tasks.values())})


@app.route('/tasks', methods=['POST'])
def create_task():
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400
    task = {'id': next_id[0], 'title': data['title']}
    tasks[next_id[0]] = task
    next_id[0] += 1
    return jsonify(task), 201
